		source:
			'"use client";\n\nimport * as React from "react";\nimport { GripVerticalIcon } from "lucide-react";\nimport { useState, type ComponentProps } from "react";\nimport { Badge } from "@workspace/ui/components/badge";\nimport { Kanban, KanbanBoard, KanbanColumn, KanbanColumnContent, KanbanColumnHandle, KanbanItem, KanbanItemHandle, KanbanOverlay } from "@workspace/ui/components/kanban";\n\nimport { Avatar, AvatarFallback, AvatarImage } from "@workspace/ui/components/avatar";\nimport { Button } from "@workspace/ui/components/button";\nimport { Card, CardContent, CardHeader } from "@workspace/ui/components/card";\n\ninterface Task {\n\tid: string;\n\ttitle: string;\n\tpriority: "low" | "medium" | "high";\n\tdescription?: string;\n\tassignee?: string;\n\tassigneeAvatar?: string;\n\tdueDate?: string;\n}\n\nconst COLUMN_TITLES: Record<string, string> = {\n\tbacklog: "Backlog",\n\tinProgress: "In Progress",\n\tdone: "Done",\n};\n\ninterface TaskCardProps extends Omit<ComponentProps<typeof KanbanItem>, "value" | "children"> {\n\ttask: Task;\n\tasHandle?: boolean | undefined;\n\tisOverlay?: boolean | undefined;\n}\n\nfunction TaskCard({ task, asHandle, isOverlay, ...props }: TaskCardProps): React.JSX.Element {\n\tconst cardContent = (\n\t\t<Card>\n\t\t\t<CardContent className="space-y-2.5">\n\t\t\t\t<div className="flex items-center justify-between gap-2">\n\t\t\t\t\t<span className="line-clamp-1 text-sm font-medium">{task.title}</span>\n\t\t\t\t\t<Badge\n\t\t\t\t\t\tvariant={task.priority === "high" ? "destructive-light" : task.priority === "medium" ? "primary-light" : "warning-light"}\n\t\t\t\t\t\tclassName="pointer-events-none h-5 shrink-0 rounded-sm px-1.5 text-xs capitalize">\n\t\t\t\t\t\t{task.priority}\n\t\t\t\t\t</Badge>\n\t\t\t\t</div>\n\t\t\t\t<div className="flex items-center justify-between text-xs text-muted-foreground">\n\t\t\t\t\t{task.assignee ? (\n\t\t\t\t\t\t<div className="flex items-center gap-1">\n\t\t\t\t\t\t\t<Avatar className="size-4">\n\t\t\t\t\t\t\t\t<AvatarImage src={task.assigneeAvatar} />\n\t\t\t\t\t\t\t\t<AvatarFallback>{task.assignee.charAt(0)}</AvatarFallback>\n\t\t\t\t\t\t\t</Avatar>\n\t\t\t\t\t\t\t<span className="line-clamp-1">{task.assignee}</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t) : null}\n\t\t\t\t\t{task.dueDate ? <time className="text-[10px] whitespace-nowrap tabular-nums">{task.dueDate}</time> : null}\n\t\t\t\t</div>\n\t\t\t</CardContent>\n\t\t</Card>\n\t);\n\n\treturn (\n\t\t<KanbanItem value={task.id} {...props}>\n\t\t\t{asHandle && !isOverlay ? <KanbanItemHandle>{cardContent}</KanbanItemHandle> : cardContent}\n\t\t</KanbanItem>\n\t);\n}\n\ninterface TaskColumnProps extends Omit<ComponentProps<typeof KanbanColumn>, "children"> {\n\ttasks: Task[];\n\tisOverlay?: boolean | undefined;\n}\n\nfunction TaskColumn({ value, tasks, isOverlay, ...props }: TaskColumnProps): React.JSX.Element {\n\treturn (\n\t\t<KanbanColumn value={value} {...props}>\n\t\t\t<Card className="mb-2.5">\n\t\t\t\t<CardHeader className="flex items-center justify-between">\n\t\t\t\t\t<div className="flex items-center gap-2.5">\n\t\t\t\t\t\t<span className="text-sm font-semibold">{COLUMN_TITLES[value]}</span>\n\t\t\t\t\t\t<Badge variant="outline">{tasks.length}</Badge>\n\t\t\t\t\t</div>\n\t\t\t\t\t<KanbanColumnHandle render={COLUMN_HANDLE_BUTTON}>\n\t\t\t\t\t\t<GripVerticalIcon />\n\t\t\t\t\t</KanbanColumnHandle>\n\t\t\t\t</CardHeader>\n\t\t\t\t<CardContent>\n\t\t\t\t\t<KanbanColumnContent value={value} className="flex flex-col gap-2.5">\n\t\t\t\t\t\t{tasks.map((task) => (\n\t\t\t\t\t\t\t<TaskCard key={task.id} task={task} asHandle={!isOverlay} isOverlay={isOverlay} />\n\t\t\t\t\t\t))}\n\t\t\t\t\t</KanbanColumnContent>\n\t\t\t\t</CardContent>\n\t\t\t</Card>\n\t\t</KanbanColumn>\n\t);\n}\n\n/** Each card\'s stable id, which the board tracks it by. */\nfunction itemId(item: Task): string {\n\treturn item.id;\n}\n\n/** The column drag handle renders as a ghost icon button. */\nconst COLUMN_HANDLE_BUTTON: React.JSX.Element = <Button size="icon-xs" variant="ghost" aria-label="Drag column" />;\n\nexport function Kanban1Example(): React.JSX.Element {\n\tconst [columns, setColumns] = useState<Record<string, Task[]>>({\n\t\tbacklog: [\n\t\t\t{\n\t\t\t\tid: "1",\n\t\t\t\ttitle: "Add authentication",\n\t\t\t\tpriority: "high",\n\t\t\t\tassignee: "Alex Johnson",\n\t\t\t\tassigneeAvatar: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=96&h=96&dpr=2&q=80",\n\t\t\t\tdueDate: "Jan 10, 2025",\n\t\t\t},\n\t\t\t{\n\t\t\t\tid: "2",\n\t\t\t\ttitle: "Create API endpoints",\n\t\t\t\tpriority: "medium",\n\t\t\t\tassignee: "Sarah Chen",\n\t\t\t\tassigneeAvatar: "https://images.unsplash.com/photo-1519699047748-de8e457a634e?w=96&h=96&dpr=2&q=80",\n\t\t\t\tdueDate: "Jan 15, 2025",\n\t\t\t},\n\t\t\t{\n\t\t\t\tid: "3",\n\t\t\t\ttitle: "Write documentation",\n\t\t\t\tpriority: "low",\n\t\t\t\tassignee: "Michael Rodriguez",\n\t\t\t\tassigneeAvatar: "https://images.unsplash.com/photo-1584308972272-9e4e7685e80f?w=96&h=96&dpr=2&q=80",\n\t\t\t\tdueDate: "Jan 20, 2025",\n\t\t\t},\n\t\t],\n\t\tinProgress: [\n\t\t\t{\n\t\t\t\tid: "4",\n\t\t\t\ttitle: "Design system updates",\n\t\t\t\tpriority: "high",\n\t\t\t\tassignee: "Emma Wilson",\n\t\t\t\tassigneeAvatar: "https://images.unsplash.com/photo-1485893086445-ed75865251e0?w=96&h=96&dpr=2&q=80",\n\t\t\t\tdueDate: "Aug 25, 2025",\n\t\t\t},\n\t\t\t{\n\t\t\t\tid: "5",\n\t\t\t\ttitle: "Implement dark mode",\n\t\t\t\tpriority: "medium",\n\t\t\t\tassignee: "David Kim",\n\t\t\t\tassigneeAvatar: "https://images.unsplash.com/photo-1607990281513-2c110a25bd8c?w=96&h=96&dpr=2&q=80",\n\t\t\t\tdueDate: "Aug 25, 2025",\n\t\t\t},\n\t\t],\n\t\tdone: [\n\t\t\t{\n\t\t\t\tid: "7",\n\t\t\t\ttitle: "Setup project",\n\t\t\t\tpriority: "high",\n\t\t\t\tassignee: "Aron Thompson",\n\t\t\t\tassigneeAvatar: "https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=96&h=96&dpr=2&q=80",\n\t\t\t\tdueDate: "Sep 25, 2025",\n\t\t\t},\n\t\t\t{\n\t\t\t\tid: "8",\n\t\t\t\ttitle: "Initial commit",\n\t\t\t\tpriority: "low",\n\t\t\t\tassignee: "James Brown",\n\t\t\t\tassigneeAvatar: "https://images.unsplash.com/photo-1543299750-19d1d6297053?w=96&h=96&dpr=2&q=80",\n\t\t\t\tdueDate: "Sep 20, 2025",\n\t\t\t},\n\t\t],\n\t});\n\n\treturn (\n\t\t<Kanban value={columns} onValueChange={setColumns} getItemValue={itemId}>\n\t\t\t<KanbanBoard className="grid auto-rows-fr grid-cols-3">\n\t\t\t\t{Object.entries(columns).map(([columnValue, tasks]) => (\n\t\t\t\t\t<TaskColumn key={columnValue} value={columnValue} tasks={tasks} />\n\t\t\t\t))}\n\t\t\t</KanbanBoard>\n\t\t\t<KanbanOverlay className="rounded-md border-2 border-dashed bg-muted/10" />\n\t\t</Kanban>\n\t);\n}\n',
